import React, { useEffect, useState } from 'react';
import {
    Box,
    FormControlLabel,
    MenuItem,
    Select,
    TextField,
    Typography,
    Checkbox,
    RadioGroup,
    Radio,
    FormLabel,
    FormGroup,
    Button // Import Button component
} from '@mui/material';

// Import the API function to fetch forms
import { fetchForms } from '../api/formApi';

const PreviewDynamicForm = () => {
    const [forms, setForms] = useState([]);
    const [selectedFormId, setSelectedFormId] = useState(''); // Store the ID of the selected form
    const [selectedFormDetails, setSelectedFormDetails] = useState(null);

    useEffect(() => {
        // Fetch forms from the database when the component mounts
        fetchForms()
            .then(data => {
                setForms(data);
            })
            .catch(error => {
                console.error('Error fetching forms:', error);
                alert('Failed to load forms.');
            });
    }, []);

    const handleFormSelect = (event) => {
        const formId = event.target.value;
        setSelectedFormId(formId);
        const formObject = forms.find((f) => f.id === parseInt(formId, 10));
        setSelectedFormDetails(formObject?.form_data || null);
    };

    // Find the name of the currently selected form for the dropdown display
    const selectedFormName = forms.find(form => form.id === parseInt(selectedFormId, 10))?.form_data?.formName || '';

    return (
        <Box p={2}>
            {/* Form Selection Dropdown */}
            <Box mb={3}>
                <Typography variant="h6" gutterBottom>Select a Form to Preview</Typography>
                <Select
                    value={selectedFormId} // Use selectedFormId for the value
                    onChange={handleFormSelect}
                    displayEmpty
                    fullWidth
                >
                    <MenuItem value="" disabled>Select Form</MenuItem>
                    {forms.map((form) => (
                        <MenuItem key={form.id} value={form.id}>
                            {form.form_data?.formName}
                        </MenuItem>
                    ))}
                </Select>
            </Box>

            {/* Form Preview */}
            {selectedFormDetails && (
                <Box>
                    {/* Form Name */}
                    <Typography variant="h5" gutterBottom>
                        {selectedFormDetails.formName}
                    </Typography>

                    {/* Form Description */}
                    <Typography variant="subtitle1" gutterBottom>
                        {selectedFormDetails.formDescription}
                    </Typography>

                    {/* Form Fields */}
                    <form>
                        {selectedFormDetails.fields.map((field, index) => (
                            <Box key={index} mb={2}>
                                {/* Text / Number / Password / Email Fields */}
                                {(field.controlType === 'text' ||
                                    field.controlType === 'number' ||
                                    field.controlType === 'email' ||
                                    field.controlType === 'password') && (
                                        <TextField
                                            label={field.label}
                                            type={field.controlType}
                                            placeholder={field.placeholder}
                                            required={field.validations?.includes('required')}
                                            inputProps={{
                                                minLength: field.minLength || undefined,
                                                maxLength: field.maxLength || undefined,
                                            }}
                                            helperText={field.helperText}
                                            fullWidth
                                        />
                                    )}

                                {/* Checkbox Group (Vertical) */}
                                {field.controlType === 'checkbox' && (
                                    <FormGroup>
                                        <FormLabel component="legend">{field.label}</FormLabel>
                                        {field.options?.map((option, idx) => (
                                            <FormControlLabel
                                                key={idx}
                                                control={<Checkbox />}
                                                label={option}
                                            />
                                        ))}
                                    </FormGroup>
                                )}

                                {/* Radio Group (Horizontal) */}
                                {field.controlType === 'radio' && (
                                    <Box>
                                        <FormLabel component="legend">{field.label}</FormLabel>
                                        <RadioGroup row>
                                            {field.options?.map((option, idx) => (
                                                <FormControlLabel
                                                    key={idx}
                                                    value={option}
                                                    control={<Radio />}
                                                    label={option}
                                                />
                                            ))}
                                        </RadioGroup>
                                    </Box>
                                )}

                                {/* Button */}
                                {field.controlType === 'button' && (
                                    <Button
                                        key={field.id} // Use field.id as key for buttons
                                        variant="contained"
                                        color="primary" // You can customize the color
                                    >
                                        {field.label}
                                    </Button>
                                )}
                            </Box>
                        ))}
                    </form>
                </Box>
            )}
        </Box>
    );
};

export default PreviewDynamicForm;
